const produk = [
  { nama: "Pensil", stok: 0 },
  { nama: "Buku", stok: 5 },
  { nama: "Pulpen", stok: 3 },
];
const tersedia = produk.filter(p => p.stok > 0);
console.log(tersedia.length);
const totalStok = produk.reduce((total, p) => total + p.stok, 0);
console.log(totalStok);

