cards.solution:
const transaksi = [30000, 70000, 20000, 110000];
const besar = transaksi.filter(t => t > 50000);
console.log(`Jumlah: ${besar.length}`);
const total = besar.reduce((akumulator, t) => akumulator + t, 0);
console.log(`Total: ${total}`);
